INSERT OR IGNORE INTO Post (id, title, slug, content, excerpt, featuredImage, type, createdAt, updatedAt) VALUES (11033, 'Các loại nội dung quảng cáo chính trên Facebook', 'cac-loai-quang-cao-tren-facebook', '
<p>Các nhà quảng cáo trên Facebook có rất nhiều tùy chọn nhắm mục tiêu và chiến dịch để lựa chọn. Không có gì ngạc nhiên khi các doanh nghiệp thuộc mọi quy mô—từ cửa hàng nhỏ và cửa hàng nhỏ cho đến các công ty trong danh sách Fortune 100—sử dụng quảng cáo trên Facebook</p>



<p>Mặc dù việc có quyền truy cập vào vô số tùy chọn quảng cáo là giấc mơ trở thành hiện thực của nhà tiếp thị nhưng điều đó cũng có thể khiến việc bắt đầu trở thành một nhiệm vụ khó khăn. Nếu bạn cảm thấy choáng ngợp, hãy xem các loại quảng cáo Facebook sau để biết cách áp dụng chúng vào chiến lược quảng cáo trên Facebook của mình.</p>



<h2 class="wp-block-heading">Quảng cáo hình ảnh</h2>



<p>Quảng cáo hình ảnh trên Facebook hoặc quảng cáo ảnh, như một số người gọi, có hình ảnh tĩnh, bản sao kèm theo và lời kêu gọi hành động (CTA).</p>



<p>Nhiều nhà quảng cáo thương mại điện tử sử dụng quảng cáo hình ảnh để quảng cáo sản phẩm và bao gồm liên kết đến trang sản phẩm.</p>



<p>Facebook cho phép bạn đặt văn bản lên quảng cáo hình ảnh của mình, nhưng họ khuyên bạn nên giữ chữ ở mức dưới 20% hình ảnh. Quá nhiều từ có thể khiến người dùng mất tập trung và cũng có thể dẫn đến việc quảng cáo của bạn bị từ chối. Trong trường hợp đó, bạn cần phải xem xét, cập nhật và gửi lại.</p>



<p></p>



<figure class="wp-block-image size-large"><img loading="lazy" decoding="async" width="1024" height="720" src="https://media.huynhhieutravel.com/cac-dinh-dang-quang-cao-hinh-anh-facebook-1024x720.jpg" alt="Một số định dạng quảng cáo hình ảnh Facebook" class="wp-image-11035"/><figcaption class="wp-element-caption">Một số định dạng quảng cáo hình ảnh Facebook</figcaption></figure>



<h2 class="wp-block-heading">Quảng cáo video</h2>



<p>Quảng cáo video trên Facebook rất giống với quảng cáo hình ảnh, điểm khác biệt nằm ở định dạng nội dung. Quảng cáo video có đồ họa video hoặc chuyển động, trong khi quảng cáo hình ảnh vẫn là ảnh hoặc đồ họa. Bạn có thể tạo quảng cáo video trên Facebook hoặc quảng cáo các bài đăng tự nhiên có video.</p>



<p>Quảng cáo video có xu hướng hấp dẫn hơn quảng cáo hình ảnh.</p>



<ul class="wp-block-list">
<li>Video trên Facebook tạo ra ít nhất 8 tỷ lượt xem mỗi ngày</li>



<li>Gần 50% thời gian trên Facebook được dành để xem video</li>



<li>46% người dùng mạng xã hội sử dụng Facebook để xem video</li>
</ul>



<p>Tuy nhiên, việc sản xuất video cũng có thể phức tạp và tốn kém hơn.</p>



<p>Khi sử dụng quảng cáo video trên Facebook, bạn có thể chọn từ nhiều vị trí và mục tiêu khác nhau. Các thông số này xác định yêu cầu về video của bạn, bao gồm kích thước quảng cáo trên Facebook, tỷ lệ khung hình và thời lượng video.</p>



<h2 class="wp-block-heading"><a href="https://www.facebook.com/business/ads/instant-experiences-ad-destination" target="_blank" rel="noreferrer noopener">Quảng cáo Trải nghiệm tức thì</a></h2>



<p>Trải nghiệm tức thì của Facebook (trước đây là Canvas) là loại quảng cáo đa phương tiện, toàn màn hình mang lại trải nghiệm nội dung phong phú cho khán giả.</p>



<p>Trải nghiệm tức thì bao gồm rất nhiều tính năng và khả năng của các loại quảng cáo khác trên Facebook—người dùng có thể xem hình ảnh, xem video, vuốt qua băng chuyền, nhấp qua các sản phẩm được gắn thẻ và thậm chí nghiêng để xoay để có những góc độc đáo.</p>



<p><strong>Xem trực tiếp quảng cáo trên: <a href="https://www.facebook.com/business/ads/instant-experiences-ad-destination" target="_blank" rel="noreferrer noopener">Quảng cáo trải nghiệm tức thì của Facebook</a>.</strong></p>



<p>Trải nghiệm tức thì là loại quảng cáo có tính hấp dẫn cao của Facebook và tận dụng sự kết hợp của các nội dung để tạo ra trải nghiệm sống động cho người dùng. Trong nhiều trường hợp, bạn có thể sử dụng hình ảnh và video mình đã tạo cho các loại quảng cáo khác trên Facebook rồi sử dụng lại chúng trong gói Trải nghiệm tức thì.</p>



<p>Đây là một cách tuyệt vời để tận dụng tối đa khoản đầu tư của bạn vào nội dung quảng cáo trên Facebook.</p>



<h2 class="wp-block-heading"><a href="https://www.facebook.com/business/ads/carousel-ad-format" target="_blank" rel="noreferrer noopener">Quảng cáo quay vòng</a> (Carousel)</h2>



<p>Quảng cáo quay vòng trên Facebook có tối đa 10 hình ảnh hoặc video ở định dạng mà người dùng có thể nhấp qua. Mỗi hình ảnh hoặc video có thể có một liên kết duy nhất, vì vậy đây là loại quảng cáo tuyệt vời trên Facebook nếu bạn đang quảng cáo bộ sưu tập sản phẩm chẳng hạn.</p>



<figure class="wp-block-image size-large"><img decoding="async" src="https://www.wordstream.com/wp-content/uploads/2021/07/facebook-carousel-ads.gif" alt=""/></figure>



<p>Bạn cũng có thể liên kết tất cả chúng với cùng một URL. URL này hoạt động tốt nếu bạn đang quảng cáo một sản phẩm nhưng muốn làm nổi bật nhiều tính năng khác nhau.</p>



<p>Bạn có thể đặt thứ tự hình ảnh và video hoặc để thuật toán của Facebook làm việc đó cho bạn, sắp xếp chúng theo thứ tự thúc đẩy nhiều chuyển đổi nhất.</p>



<h2 class="wp-block-heading"><a href="https://www.facebook.com/business/ads/slideshow-ad-format" target="_blank" rel="noreferrer noopener">Quảng cáo trình chiếu</a> (Slideshow)</h2>



<p>Nếu bạn đang tìm cách sử dụng lại nội dung quảng cáo mình đã có thì quảng cáo bản trình chiếu trên Facebook có thể phù hợp với bạn. Về cơ bản, Facebook lấy quảng cáo hình ảnh của bạn và ghép các tệp lại với nhau ở định dạng video trình chiếu.</p>



<p>Loại quảng cáo Facebook này sẽ giúp bạn tận dụng sức mạnh của video mà không cần thêm ngân sách cho video, vốn có thể tốn kém để sản xuất.</p>



<p>Nếu bạn có quảng cáo hình ảnh trên Facebook có hiệu suất cao, bạn có thể xem xét biến chúng thành quảng cáo video trình chiếu. Bạn có thể thực hiện tất cả những điều này trong Facebook, cũng như thêm ảnh và nhạc có sẵn cho đa dạng.</p>



<h2 class="wp-block-heading"><a href="https://www.facebook.com/business/ads/collection-ad-format" target="_blank" rel="noreferrer noopener">Quảng cáo bộ sưu tập</a></h2>



<p>Quảng cáo bộ sưu tập trên Facebook được định hướng thương mại điện tử và đặc biệt nhằm biến người duyệt Facebook thành người mua trực tuyến. Quảng cáo bộ sưu tập có hình ảnh hoặc video nổi bật chính cũng như 3 hình ảnh nhỏ hơn bên dưới. Khi người dùng nhấp vào quảng cáo bộ sưu tập, họ sẽ được đưa đến Trải nghiệm tức thì.</p>



<figure class="wp-block-image size-full"><img loading="lazy" decoding="async" width="652" height="367" src="https://media.huynhhieutravel.com/vi-du-quang-cao-bo-suu-tap.webp" alt="Ví dụ quảng cáo bộ sưu tập" class="wp-image-11040"/><figcaption class="wp-element-caption">Ví dụ quảng cáo bộ sưu tập</figcaption></figure>



<p>Có 3 mẫu cho quảng cáo bộ sưu tập trên Facebook:</p>



<ol class="wp-block-list">
<li>Instant Storefront nếu bạn có 4 sản phẩm trở lên và muốn tập trung vào việc mua sản phẩm của mình.</li>



<li>Lookbook tức thì về phong cách sống và hình ảnh theo ngữ cảnh thể hiện (các) sản phẩm của bạn đang hoạt động đồng thời kể câu chuyện thương hiệu của bạn.</li>



<li>Thu hút khách hàng tức thì để tập trung vào việc thúc đẩy chuyển đổi trên thiết bị di động hoặc các hành động khác.</li>
</ol>



<h2 class="wp-block-heading">Quảng cáo danh mục Advantage+ (Trước đây được gọi là Quảng cáo động)</h2>



<p>Quảng cáo động trên Facebook kết nối danh mục sản phẩm của cửa hàng với Trình quản lý sự kiện trên Facebook và pixel Facebook của bạn.</p>



<p>Khi ai đó truy cập trang web của bạn rồi đăng nhập vào Facebook, họ sẽ thấy quảng cáo giới thiệu các sản phẩm giống như sản phẩm họ đang xem trên trang web của bạn. Kết quả là quảng cáo họ nhìn thấy cực kỳ được cá nhân hóa và phù hợp.</p>



<p>Quảng cáo động thường ở định dạng quảng cáo quay vòng. Bạn cũng có thể áp dụng đối tượng tùy chỉnh cho quảng cáo động của mình, cho phép bạn sắp xếp nhiều bộ sưu tập mục được nhắm mục tiêu hơn dựa trên những người sẽ xem nó.</p>



<p><strong>Ví dụ: có thể bạn có danh mục sản phẩm trên trang web của mình. Bạn có thể tạo quảng cáo quay vòng cho các danh mục khác nhau và hiển thị chúng cho người dùng đã truy cập các trang trong danh mục tương ứng.</strong></p>



<p>Khi bạn chạy quảng cáo động, bản sao cho tất cả những người nhìn thấy quảng cáo đó là giống nhau nhưng quảng cáo này độc đáo 100% và được cá nhân hóa dựa trên hành vi của người xem tương ứng trên trang web của bạn.</p>



<p>Với quảng cáo động, bạn có thể chọn bốn đối tượng khác nhau để nhắm mục tiêu:</p>



<ul class="wp-block-list">
<li>Đã xem nhưng chưa mua</li>



<li>Đã thêm vào giỏ hàng nhưng chưa mua</li>



<li>Bán thêm sản phẩm</li>



<li>Bán chéo sản phẩm</li>



<li>Dựa trên đối tượng bạn đã chọn, quảng cáo sẽ tự động được tối ưu hóa cho từng mục tiêu, giúp bạn tiết kiệm thời gian và mang lại kết quả tốt hơn.</li>
</ul>



<h2 class="wp-block-heading">Quảng cáo trên Messenger</h2>



<p>Quảng cáo trên Facebook Messenger xuất hiện trong tab trò chuyện của người dùng cũng như giữa các Câu chuyện trên Messenger. Bạn có thể sử dụng nội dung quảng cáo từ các loại quảng cáo khác của Facebook và đặt thông số nhắm mục tiêu và vị trí của mình, sau đó Facebook sẽ thực hiện phần việc còn lại.</p>



<p>Khi ai đó nhấn vào quảng cáo Messenger của bạn, họ sẽ được đưa đến điểm đến mà bạn chọn (trang web, ứng dụng hoặc tin nhắn trực tiếp với trang Facebook của bạn).</p>



<h2 class="wp-block-heading">Quảng cáo Stories</h2>



<p>Quảng cáo Stories trên Facebook&nbsp;hiển thị khi người dùng đang xem Stories thay vì cuộn qua nguồn cấp tin tức của họ.&nbsp;Theo Facebook, mọi người yêu thích Stories.</p>



<p>Quảng cáo trên Stories xuất hiện ở định dạng dọc, vì vậy hãy ghi nhớ điều đó khi tạo hình ảnh và video để sử dụng trong loại quảng cáo Facebook này. Bạn cũng có thể đẩy những quảng cáo này lên Instagram và Messenger.</p>
', 'Các loại nội dung quảng cáo chính trên Facebook: Hình ảnh, video, trải nghiệm tức thì, quay vòng, trình chiếu, bộ sưu tập, Advantage+ ,&#8230;', 11045, 'post', '2023-10-12 11:32:04', '2023-10-12 11:45:37');

