INSERT OR IGNORE INTO Post (id, title, slug, content, excerpt, featuredImage, type, createdAt, updatedAt) VALUES (10799, 'Lời nhắc nâng cao cho ChatGPT', 'loi-nhac-nang-cao-cho-chatgpt', '		<div data-elementor-type="wp-post" data-elementor-id="10799" class="elementor elementor-10799" data-elementor-post-type="post">
				<div class="elementor-element elementor-element-fe35e80 e-con-full e-flex e-con e-parent" data-id="fe35e80" data-element_type="container" data-settings="{&quot;jet_parallax_layout_list&quot;:[],&quot;background_background&quot;:&quot;classic&quot;}">
		<div class="elementor-element elementor-element-6195242 e-con-full e-flex e-con e-child" data-id="6195242" data-element_type="container" data-settings="{&quot;jet_parallax_layout_list&quot;:[],&quot;background_background&quot;:&quot;classic&quot;}">
